() => {
  const pageData = window.__svelteData || window.__NEXT_DATA__ || document.documentElement.innerHTML;
  const timeRegex = /(kick.{0,5}off|start.{0,5}time|15:00|17:30|20:00|19:45)/gi;
  const matches = pageData.match(timeRegex);
  return JSON.stringify(matches);
}

() => {
  // Look for kickoff time in meta tags and structured data
  const meta = document.querySelector('meta[property="article:published_time"]');
  const jsonLd = document.querySelectorAll('script[type="application/ld+json"]');
  const html = document.documentElement.innerHTML;

  // Find any times on the page that might be kickoff
  const timeElements = document.querySelectorAll('time, [datetime]');
  const times = [];
  timeElements.forEach(t => {
    if (t.datetime || t.textContent) {
      times.push({dt: t.datetime, text: t.textContent.substring(0, 50)});
    }
  });

  // Search for kickoff in page text
  const kickoffMatch = html.match(/kick[ -]?off[^<]{0,100}/gi);

  return JSON.stringify({
    meta: meta ? meta.content : null,
    times: times.slice(0, 30),
    kickoff: kickoffMatch ? kickoffMatch.slice(0, 5) : null
  });
}

() => {
  // Find any JSON data containing match info
  const scripts = document.querySelectorAll('script');
  const data = [];
  scripts.forEach((s, i) => {
    const text = s.textContent;
    if (text.includes('kickoffTime') || text.includes('startTime') || text.includes('Hibernian') || text.includes('kickOff')) {
      // Extract relevant portions
      const koMatch = text.match(/kickoffTime[^,}]{0,50}/g);
      const soMatch = text.match(/startTime[^,}]{0,50}/g);
      const koAlt = text.match(/kickOff[^,}]{0,50}/g);
      data.push({i, koMatch, soMatch, koAlt});
    }
  });
  return JSON.stringify(data);
}

() => {
  const html = document.documentElement.innerHTML;

  // Find time patterns
  const patterns = [
    /\b\d{1,2}:\d{2}\b/g,
    /kick[\s_-]?off[^A-Za-z0-9]{0,5}[A-Za-z0-9\s:]{0,30}/gi,
    /start[\s_-]?time[^A-Za-z0-9]{0,5}[A-Za-z0-9\s:]{0,30}/gi,
    /KO[^A-Za-z0-9]{0,5}\d{1,2}[:.]\d{2}/g,
    /commenced[^.]{0,50}/gi,
    /kick[^.]{0,50}/gi
  ];

  const results = {};
  patterns.forEach((p, i) => {
    const m = html.match(p);
    if (m) results[i] = m.slice(0, 10);
  });
  return JSON.stringify(results, null, 2);
}

() => {
  const html = document.documentElement.innerHTML;

  // Just dump the area around "kick" and any time-like patterns
  const allTimes = html.match(/\b\d{1,2}[:.]\d{2}\b/g);
  const allKickoffs = html.match(/[Kk]ick[^\n]{0,100}/g);
  const allStarts = html.match(/[Ss]tart[^\n]{0,100}/g);
  const allKickOff = html.match(/[Kk]ickOff[^\n]{0,100}/g);

  return JSON.stringify({
    times: allTimes ? allTimes.slice(0, 30) : null,
    kickoffs: allKickoffs ? allKickoffs.slice(0, 10) : null,
    starts: allStarts ? allStarts.slice(0, 10) : null,
    kickoff: allKickOff ? allKickOff.slice(0, 10) : null,
    htmlLength: html.length
  }, null, 2);
}

() => {
  const html = document.documentElement.innerHTML;

  // Search for times in HH:MM or H:MM format
  const allTimes = html.match(/\b\d{1,2}[:.]\d{2}\b/g);
  // Search for kickoff in various forms
  const allKickoffs = html.match(/[Kk]ick[^\n]{0,100}/g);
  const allStarts = html.match(/[Ss]tart[^\n]{0,100}/g);
  const allKickOff = html.match(/[Kk]ickOff[^\n]{0,100}/g);

  return JSON.stringify({
    times: allTimes ? [...new Set(allTimes)].slice(0, 30) : null,
    kickoffs: allKickoffs ? allKickoffs.slice(0, 10) : null,
    starts: allStarts ? allStarts.slice(0, 10) : null,
    kickoff: allKickOff ? allKickOff.slice(0, 10) : null,
    htmlLength: html.length
  }, null, 2);
}

() => {
  // Find the H1 or date elements
  const dateElems = document.querySelectorAll('time, [data-testid*="date"]');
  const results = [];
  dateElems.forEach(el => {
    results.push({
      tag: el.tagName,
      datetime: el.getAttribute('datetime'),
      text: el.textContent.trim().substring(0, 100)
    });
  });
  return JSON.stringify(results);
}
